            new Quote { Id = "https://en.wikiquote.org/wiki/Terry_Pratchett", Text = "It's just that it's dawned on me that 'zero tolerance' only seems to mean putting extra police in poor, run-down areas, and not in the Stock Exchange.", Author = "Terry Pratchett" },
