            new Quote { Id = "https://en.wikiquote.org/wiki/Terry_Pratchett", Text = "I think that sick people in Ankh-Morpork generally go to a vet. It's generally a better bet. There's more pressure on a vet to get it right. People say \"it was god's will\" when granny dies, but they get angry when they lose a cow.", Author = "Terry Pratchett" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Terry_Pratchett", Text = "What you have here is an example of that well known phenomenon, A Bookshop Assistant Who Knows Buggerall But Won't Admit It (probably some kind of arts graduate).", Author = "Terry Pratchett" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Terry_Pratchett", Text = "Out of Print is bookseller speak for We can't be hedgehogged.", Author = "Terry Pratchett" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Terry_Pratchett", Text = "Bognor has always meant to me the quintessential English seaside experience (before all this global warming stuff): driving in the rain to get there, walking around in the rain looking for something to do when you're there, and driving home in the rain again...", Author = "Terry Pratchett" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Terry_Pratchett", Text = "Mind you, the Elizabethans had so many words for the female genitals that it is quite hard to speak a sentence of modern English without inadvertently mentioning at least three of them.", Author = "Terry Pratchett" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Terry_Pratchett", Text = "Death isn't online. If he was, there would be a sudden drop in the death rate. Although it'd be interesting to see if he'd post things like: DON'T YOU THINK I SOUND LIKE JAMES EARL JONES?", Author = "Terry Pratchett" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Terry_Pratchett", Text = "This book had two authors, and they were both the same person.", Author = "Terry Pratchett" },
