            new Quote { Id = "https://en.wikiquote.org/wiki/Terry_Pratchett", Text = "Most armies are in fact run by their sergeants - the officers are there just to give things a bit of tone and prevent warfare from becoming a mere lower-class brawl.", Author = "Terry Pratchett" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Terry_Pratchett", Text = "The Deftmenes are mad and the Dumii are sane, thought Snibril, and that's just the same as being mad except that it's quieter. If only you could mix them together, you'd end up with normal people.", Author = "Terry Pratchett" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Terry_Pratchett", Text = "Normally its narrow streets were crowded with stalls, and people from all over the Carpet. They'd all be trying to cheat one another in that open-and-above-board way known as 'doing business'.", Author = "Terry Pratchett" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Terry_Pratchett", Text = "The sign outside the shop said Apothecary, which meant that the shop was owned by a sort of early chemist, who would give you herbs and things until you got better or at least stopped getting any worse.", Author = "Terry Pratchett" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Terry_Pratchett", Text = "What would Deftmenes be if we went around obeying orders all the time? They might be ruling the Carpet, said Pismire. Ha! said Brocando, but the trouble about obeying orders is, it becomes a habit. And then everything depends on who's giving the orders.", Author = "Terry Pratchett" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Terry_Pratchett", Text = "Waiting is the worst part, said Pismire. No it isn't, said Owlglass, who wasn't even being trusted to hold a sword. I expect that having long sharp swords stuck in you is the worst part.", Author = "Terry Pratchett" },
