            new Quote { Id = "https://en.wikiquote.org/wiki/Terry_Pratchett", Text = "It is well known that a vital ingredient of success is not knowing that what you're attempting can't be done.", Author = "Terry Pratchett" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Terry_Pratchett", Text = "Boot-faced cats aren't born but made, often because they've tried to outstare or occasionally rape a speeding car and have been repaired by a vet who just pulled all the bits together and stuck the stitches in where there was room.", Author = "Terry Pratchett" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Terry_Pratchett", Text = "Cats don't hunt seals. They would if they knew what they were and where to find them. But they don't, so that's all right.", Author = "Terry Pratchett" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Terry_Pratchett", Text = "It's an interesting fact that fewer than 17% of Real cats end their lives with the same name they started with. Much family effort goes into selecting one at the start (\"She looks like a Winnifred to me\"), and as the years roll by it suddenly finds itself being called Meepo or Ratbag.", Author = "Terry Pratchett" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Terry_Pratchett", Text = "Everyone's heard of Erwin Schrodinger's famous thought experiment. You put a cat in a box with a bottle of poison, which many people would suggest is about as far as you need to go.", Author = "Terry Pratchett" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Terry_Pratchett", Text = "The trouble with having an open mind, of course, is that people will insist on coming along and trying to put things in it.", Author = "Terry Pratchett" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Terry_Pratchett", Text = "Light thinks it travels faster than anything but it is wrong. No matter how fast light travels it finds the darkness has always got there first, and is waiting for it.", Author = "Terry Pratchett" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Terry_Pratchett", Text = "You can't go around building a better world for people. Only people can build a better world for people. Otherwise it's just a cage. Besides you don't build a better world by choppin' heads off and giving decent girls away to frogs.", Author = "Terry Pratchett" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Terry_Pratchett", Text = "Everything makes sense a bit at a time. But when you try to think of it all at once, it comes out wrong.", Author = "Terry Pratchett" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Terry_Pratchett", Text = "Suicide was against the law. Johnny had wondered why. It meant that if you missed, or the gas ran out, or the rope broke, you could get locked up in prison to show you that life was really very jolly and thoroughly worth living.", Author = "Terry Pratchett" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Terry_Pratchett", Text = "There is a rumour going around that I have found God. I think this is unlikely because I have enough difficulty finding my keys, and there is empirical evidence that they exist.", Author = "Terry Pratchett" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Terry_Pratchett", Text = "Who would not rather be a rising ape than a falling angel?", Author = "Terry Pratchett" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Terry_Pratchett", Text = "It doesn't take much to make us flip back into monkeys again.", Author = "Terry Pratchett" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Terry_Pratchett", Text = "I don't believe. I never have, not in big beards in the sky.", Author = "Terry Pratchett" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Terry_Pratchett", Text = "Belief was never mentioned at home, but right actions were taught by daily example. Possibly because of this, I have never disliked religion. I think it has some purpose in our evolution.", Author = "Terry Pratchett" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Terry_Pratchett", Text = "I don't have much truck with the \"religion is the cause of most of our wars\" school of thought because that is manifestly done by mad, manipulative and power-hungry men who cloak their ambition in God.", Author = "Terry Pratchett" },
